import{_ as i,c as t,o as a,aj as o}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse('{"title":"Colorado Style Pizza Dough","description":"Colorado Mountain Pie style dough with a thin rolled center, thick honey-dipping rim, and generous topping support.","frontmatter":{"title":"Colorado Style Pizza Dough","description":"Colorado Mountain Pie style dough with a thin rolled center, thick honey-dipping rim, and generous topping support.","head":[["meta",{"name":"description","content":"Colorado Mountain Pie style dough with a thin rolled center, thick honey-dipping rim, and generous topping support."}],["meta",{"property":"og:title","content":"Colorado Style Pizza Dough"}],["meta",{"property":"og:description","content":"Colorado Mountain Pie style dough with a thin rolled center, thick honey-dipping rim, and generous topping support."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/colorado-pizza-dough.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Colorado Style Pizza Dough"}],["meta",{"name":"twitter:description","content":"Colorado Mountain Pie style dough with a thin rolled center, thick honey-dipping rim, and generous topping support."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/colorado-pizza-dough.html"}]]},"headers":[],"relativePath":"recipes/colorado-pizza-dough.md","filePath":"recipes/colorado-pizza-dough.md"}'),r={name:"recipes/colorado-pizza-dough.md"};function l(n,e,s,h,d,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="colorado-style-pizza-dough" tabindex="-1">Colorado Style Pizza Dough <a class="header-anchor" href="#colorado-style-pizza-dough" aria-label="Permalink to “Colorado Style Pizza Dough”">​</a></h1><p>Colorado Mountain Pie style: thin rolled center, thick bread-like rim, and a honey-dipping crust. Use the <a href="https://kitchenratio.com/calculator/pizza/colorado" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch size.</p><div class="info custom-block"><p class="custom-block-title">Testing Status</p><p>This formula is still being tested and refined, especially hydration.</p></div><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>This version is adapted for home baking without commercial pizza equipment. The goal is the Colorado mountain-pie profile: a firm dough that rolls thin in the center while keeping a large rim for honey dipping.</p><p>Honey is used instead of sugar in this dough, reflecting the traditional mountain-pie style where the crust is often finished with honey.</p><h2 id="baker-s-testing-range" tabindex="-1">Baker&#39;s % (Testing Range) <a class="header-anchor" href="#baker-s-testing-range" aria-label="Permalink to “Baker&#39;s % (Testing Range)”">​</a></h2><ul><li><strong>Flour</strong> - 100%</li><li><strong>Water</strong> - 52-54% (53% strong starting point)</li><li><strong>Honey</strong> - 5%</li><li><strong>Salt</strong> - 2%</li><li><strong>Oil</strong> - 2%</li><li><strong>Instant dry yeast</strong> - 0.6%</li><li><strong>Diastatic malt powder (optional)</strong> - 0.3%</li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Bread flour works well. For a chewier crust, try a blend of <strong>70% bread flour + 30% high-gluten flour</strong>.</p></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This dough runs lower hydration than many pizza styles. That helps it roll thin in the center while supporting a thick outer rim.</p></div><hr><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 550g (100%)</li><li><strong>Water</strong> - 292g (53%)</li><li><strong>Honey</strong> - 27.5g (5%)</li><li><strong>Salt</strong> - 11g (2%)</li><li><strong>Olive oil</strong> - 11g (2%)</li><li><strong>Instant dry yeast</strong> - 3.3g (0.6%)</li><li><strong>Diastatic malt powder (optional)</strong> - 1.65g (0.3%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><h2 id="equipment" tabindex="-1">Equipment <a class="header-anchor" href="#equipment" aria-label="Permalink to “Equipment”">​</a></h2><ul><li>Mixing bowl or stand mixer</li><li>Rolling pin</li><li>Baking steel or pizza stone (recommended)</li><li>Oven that can run <strong>475-500F</strong></li></ul><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine flour, yeast, and optional diastatic malt.</li><li>Mix water and honey together first so the honey disperses evenly.</li><li>Add honey-water and oil to the dry mix.</li><li>Mix until a rough dough forms.</li><li>Add salt and knead until smooth and elastic: <ul><li><strong>8-10 minutes by hand</strong></li><li><strong>5-6 minutes in a mixer</strong></li></ul></li><li>Dough should feel firmer than typical pizza dough, but smooth.</li></ul><h3 id="_2-fermentation" tabindex="-1">2. Fermentation <a class="header-anchor" href="#_2-fermentation" aria-label="Permalink to “2. Fermentation”">​</a></h3><ul><li>Cover dough and rest <strong>20-30 minutes</strong>.</li><li>Divide and ball.</li><li>Place dough balls in lightly oiled containers.</li><li>Refrigerate <strong>24-48 hours</strong> for best flavor.</li><li>Before shaping, warm at room temperature <strong>45-60 minutes</strong>.</li></ul><h3 id="_3-dough-ball-reference" tabindex="-1">3. Dough Ball Reference <a class="header-anchor" href="#_3-dough-ball-reference" aria-label="Permalink to “3. Dough Ball Reference”">​</a></h3><table tabindex="0"><thead><tr><th>Pizza size</th><th>Dough weight</th></tr></thead><tbody><tr><td>10-11 inch</td><td>~10 oz</td></tr><tr><td>12 inch</td><td>~12-13 oz</td></tr><tr><td>14 inch</td><td>~16 oz</td></tr></tbody></table><h3 id="_4-shaping-mountain-pie-style" tabindex="-1">4. Shaping (Mountain Pie Style) <a class="header-anchor" href="#_4-shaping-mountain-pie-style" aria-label="Permalink to “4. Shaping (Mountain Pie Style)”">​</a></h3><ul><li>Lightly flour the work surface.</li><li>Flatten dough with hands.</li><li>Roll with a pin so the center is thin, about <strong>1/8 inch</strong>.</li><li>Leave a <strong>1.5-2 inch</strong> uncovered border around the edge.</li><li>Toppings go on the center only.</li></ul><h3 id="_5-form-the-rim" tabindex="-1">5. Form the Rim <a class="header-anchor" href="#_5-form-the-rim" aria-label="Permalink to “5. Form the Rim”">​</a></h3><ul><li>Roll the outer edge inward to form a thick rim.</li><li>Optional: braid/rope the rim if desired.</li><li>This thick rim is intentional and becomes the signature honey-dipping crust.</li></ul><h3 id="_6-topping" tabindex="-1">6. Topping <a class="header-anchor" href="#_6-topping" aria-label="Permalink to “6. Topping”">​</a></h3><ul><li>Sauce and toppings stay in the center.</li><li>Leave rim uncovered.</li><li>This style can handle generous toppings, but avoid flooding the center.</li></ul><h3 id="_7-bake" tabindex="-1">7. Bake <a class="header-anchor" href="#_7-bake" aria-label="Permalink to “7. Bake”">​</a></h3><ul><li>Preheat oven to <strong>475-500F</strong> with steel/stone if available.</li><li>Bake until rim is golden and cheese is bubbling, usually <strong>10-14 minutes</strong>.</li></ul><h3 id="_8-serve-traditional" tabindex="-1">8. Serve (Traditional) <a class="header-anchor" href="#_8-serve-traditional" aria-label="Permalink to “8. Serve (Traditional)”">​</a></h3><ul><li>Slice normally.</li><li>Eat the slice first, then finish the crust with honey (drizzled or dipped).</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/ingredients/flour.html">Flour</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul><h2 id="related-recipes" tabindex="-1">Related Recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to “Related Recipes”">​</a></h2><ul><li><a href="/recipes/margots-midwest-thin-deck-pizza.html">Margot&#39;s Midwest Thin (Deck)</a></li><li><a href="/recipes/cold-iron-cloud-pan-pizza.html">Cold Iron Cloud Pan Pizza</a></li></ul><hr><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',41)])])}const p=i(r,[["render",l]]);export{u as __pageData,p as default};
